#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_progress;
uniform float amzp_density;
uniform float amzp_size;
uniform float amzp_zDist;
uniform float amzp_scatter;

    float3 hash3(float2 p) {
      float3 q = float3(
        dot(p, float2(127.1, 311.7)),
        dot(p, float2(269.5, 183.3)),
        dot(p, float2(419.2, 371.9))
      );
      return fract(sin(q) * 43758.5453);
    }

    float gradientNoise(float2 p) {
      float2 i = floor(p);
      float2 f = fract(p);
      float2 u = f * f * (3.0 - 2.0 * f);

      float n = mix(
        mix(
          dot(-1.0 + 2.0 * hash3(i).xy, f - float2(0.0, 0.0)),
          dot(-1.0 + 2.0 * hash3(i + float2(1.0, 0.0)).xy, f - float2(1.0, 0.0)),
          u.x
        ),
        mix(
          dot(-1.0 + 2.0 * hash3(i + float2(0.0, 1.0)).xy, f - float2(0.0, 1.0)),
          dot(-1.0 + 2.0 * hash3(i + float2(1.0, 1.0)).xy, f - float2(1.0, 1.0)),
          u.x
        ),
        u.y
      );

      return 0.5 + 0.5 * n;
    }

    float fbm(float2 p) {
      float v = 0.0;
      float amp = 0.5;
      float freq = 1.0;
      for (int i = 0; i < 4; i++) {
        v += amp * gradientNoise(p * freq);
        freq *= 2.0;
        amp *= 0.5;
      }
      return v;
    }

    void amzRender() {
      float2 iResolution = screen.zw;
      float2 fragCoord = amzScreenNorm() * iResolution;
      float2 uv = fragCoord / iResolution;
      float aspect = iResolution.x / iResolution.y;

      float noiseScale = 3.0;
      float dissolveMap = fbm(uv * float2(aspect, 1.0) * noiseScale + 10.0);

      float t = amzp_progress * 1.6;
      float solidAlpha = smoothstep(t - 0.05, t + 0.05, dissolveMap);

      float3 finalColor = float3(0.0);

      if (solidAlpha > 0.001) {
        float3 imgCol = amzTexture(0, uv).rgb;
        finalColor = imgCol * solidAlpha;
      }

      float gridDim = amzp_density;
      float2 dims = float2(gridDim * aspect, gridDim);
      float2 cellSize = 1.0 / dims;
      float2 id = floor(uv * dims);

      int range = 2;
      for (int y = -2; y <= 2; y++) {
        for (int x = -2; x <= 2; x++) {
          float2 offset = float2(float(x), float(y));
          float2 neighborID = id + offset;

          float2 origin = (neighborID + 0.5) * cellSize;

          float3 rnd = hash3(neighborID);

          float pThreshold = fbm(origin * float2(aspect, 1.0) * noiseScale + 10.0);

          if (t < pThreshold) {
            continue;
          }

          float age = t - pThreshold;

          float z = 1.0 + (age * amzp_zDist);
          if (z < 0.05) {
            continue;
          }

          if (z > 1.0 && solidAlpha > 0.5) {
            continue;
          }

          float2 flow = float2(
            gradientNoise(neighborID * 0.1 + age),
            gradientNoise(neighborID * 0.1 + age + 100.0)
          ) - 0.5;
          float2 jitter = rnd.xy - 0.5;

          float2 posOffset = (flow * 0.8 + jitter * 0.2) * amzp_scatter * age;

          float2 worldPos = (origin - 0.5) * aspect;
          worldPos += posOffset;

          float2 projectedPos = worldPos / z;
          projectedPos.x /= aspect;
          float2 screenPos = projectedPos + 0.5;

          float2 diff = uv - screenPos;
          diff.x *= aspect;
          float dist = length(diff);

          float pSize = amzp_size * (0.8 + 0.4 * rnd.z);
          float radius = (0.5 * pSize) / amzp_density / z;

          float alpha = 1.0 - smoothstep(radius * 0.5, radius, dist);

          if (alpha > 0.0) {
            float3 pCol = amzTexture(0, origin).rgb;

            float distFade = 1.0;
            if (z > 1.0) {
              distFade = 1.0 / (1.0 + age * 2.0);
            } else {
              distFade = smoothstep(0.05, 0.3, z);
            }

            alpha *= distFade;

            finalColor = mix(finalColor, pCol, alpha);
          }
        }
      }

      amzOutput = float4(finalColor, 1.0);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

